const fs = require('fs');
const statePath = '/home/node/n8n-state/backfill-state.json';
const tmpPath = `${statePath}.tmp`;
const sessionCtx = $('Code: Parse Session Meta').item.json;
const sessionId = sessionCtx.session_id;
const outputDir = $('Code: Read Transcript').item.json.outputDir;
const ts = new Date().toISOString();

// Reload state (defensive: file may have been edited between load and now)
let state = { schema_version: '1', last_updated: null, completed: [], failed: [] };
if (fs.existsSync(statePath)) {
  try { state = JSON.parse(fs.readFileSync(statePath, 'utf8')); } catch (e) {}
}
state.completed = state.completed || [];
state.failed = state.failed || [];
state.last_updated = ts;

const body = $input.first().json;
const err = $input.first().error;

const logPath = `${outputDir}/ingest-error.log`;

function recordHttpFailure(e) {
  const report = `[${ts}] /ingest failed after retry for ${sessionId}\nstatus: ${e.httpCode || 'n/a'}\nmessage: ${e.message || JSON.stringify(e)}\nresponse: ${JSON.stringify(e.response || body || {}, null, 2)}\n`;
  try { fs.writeFileSync(logPath, report, 'utf8'); } catch (x) {}
  state.failed = state.failed.filter(x => x.session_id !== sessionId);
  state.failed.push({ session_id: sessionId, failed_at: ts, reason: e.message || 'http error' });
}

function recordShapeFailure(b) {
  const report = `[${ts}] /ingest returned unexpected response shape for ${sessionId}\nbody: ${JSON.stringify(b || {}, null, 2)}\n`;
  try { fs.writeFileSync(logPath, report, 'utf8'); } catch (x) {}
  state.failed = state.failed.filter(x => x.session_id !== sessionId);
  state.failed.push({ session_id: sessionId, failed_at: ts, reason: 'unexpected response shape' });
}

function recordPartial(b) {
  const warnings = b.warnings || [];
  const warningsText = warnings.length ? ('\n  - ' + warnings.join('\n  - ')) : ' (none)';
  const report = `[${ts}] /ingest partial failure for ${sessionId}\nchunks_written:  ${b.chunks_written}\nchunks_failed:   ${b.chunks_failed}\nchunks_skipped:  ${b.chunks_skipped_idempotent}\nchunks_by_type:  ${JSON.stringify(b.chunks_by_type || {})}\nwarnings:${warningsText}\n\nPartial failures typically mean LLM retry exhaustion for\nindividual chunks. Re-run with force_reextract=true once\nthe underlying rate-limit or API issue resolves.\n`;
  try { fs.writeFileSync(logPath, report, 'utf8'); } catch (e) {}
  state.failed = state.failed.filter(e => e.session_id !== sessionId);
  state.failed.push({ session_id: sessionId, failed_at: ts, reason: `partial: ${b.chunks_failed} failed of ${b.chunks_written + b.chunks_failed}` });
}

function recordPipelineFailure(message) {
  const pipelineLogPath = `${outputDir}/pipeline-error.log`;
  const report = `[${ts}] chunked LLM pipeline failed for ${sessionId}\nmessage: ${message}\n`;
  try { fs.writeFileSync(pipelineLogPath, report, 'utf8'); } catch (x) {}
  state.failed = state.failed.filter(x => x.session_id !== sessionId);
  state.failed.push({ session_id: sessionId, failed_at: ts, reason: message });
}

function recordSuccess(b) {
  // Clear stale error log from prior failed/partial run
  try { if (fs.existsSync(logPath)) fs.unlinkSync(logPath); } catch (e) {}
  state.failed = state.failed.filter(e => e.session_id !== sessionId);
  // Dedup: remove any prior completed entry for this session_id
  state.completed = state.completed.filter(e => e.session_id !== sessionId);
  state.completed.push({
    session_id: sessionId,
    completed_at: ts,
    chunks_written: b.chunks_written
  });
}

if (err) {
  recordHttpFailure(err);
} else if (body && typeof body.pipelineFailureMessage === 'string') {
  recordPipelineFailure(body.pipelineFailureMessage);
} else if (!body || typeof body.chunks_written !== 'number') {
  recordShapeFailure(body);
} else if ((body.chunks_failed || 0) > 0) {
  recordPartial(body);
} else {
  recordSuccess(body);
}

fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), 'utf8');
fs.renameSync(tmpPath, statePath);

const pipelineFailed = body && typeof body.pipelineFailureMessage === 'string';
return { json: { session_id: sessionId, ingest_status: err ? 'failed' : (pipelineFailed ? 'pipeline_failed' : ((body && body.chunks_failed > 0) ? 'partial' : 'ok')) } };

const fs = require('fs');
const path = '/home/node/n8n-state/backfill-state.json';

let state = { schema_version: '1', last_updated: null, completed: [], failed: [] };
let existed = false;
if (fs.existsSync(path)) {
  existed = true;
  try {
    state = JSON.parse(fs.readFileSync(path, 'utf8'));
  } catch (e) {
    return { json: {
      summary: `Backfill run complete. State file at ${path} was unparseable: ${e.message}`,
      totalCompleted: 0, totalFailed: 0, error: e.message
    } };
  }
}

const totalCompleted = (state.completed || []).length;
const totalFailed = (state.failed || []).length;
const recentFailures = (state.failed || [])
  .slice(-5)
  .map(f => `  - ${f.session_id}: ${f.reason}`)
  .join('\n') || '  (none)';

const fileNote = existed ? '' : '\n(NOTE: state file did not exist -- workflow may not have processed any sessions)';

const summary = `Backfill run complete.${fileNote}

Completed (cumulative): ${totalCompleted}
Failed (cumulative):    ${totalFailed}
Last-updated:           ${state.last_updated}

Recent failures:
${recentFailures}
`;
console.log(summary);
return { json: { summary, totalCompleted, totalFailed, stateFileExisted: existed } };

return [{
  json: {
    steps: {
      prep:         { model: 'anthropic/claude-sonnet-5', maxTokens: 32768, chunkTargetTokens: 15000 },
      signalMap:    { model: 'anthropic/claude-sonnet-5', maxTokens: 16384, chunkTargetTokens: 15000 },
      signalReduce: { model: 'anthropic/claude-sonnet-5', maxTokens: 32768, budgetTokens: 8000 },
      postSection:  { model: 'z-ai/glm-5.3-flash',        maxTokens: 16384, reasoningEffort: 'low' },
      compress:     { model: 'z-ai/glm-5.3-flash',        maxTokens: 16384, reasoningEffort: 'low' },
      invite:       { model: 'z-ai/glm-5.3-flash',        maxTokens: 16384, reasoningEffort: 'low' },
    },
    retry: { componentAttempts: 3, callerHalvings: 2 },
  },
}];

const cfg = $('Code: Pipeline Config').first().json.steps.prep;
const src = $('Code: Read Transcript').first().json.transcriptText;
const halving = $input.first().json.halving || 0;
const target = Math.floor(cfg.chunkTargetTokens / Math.pow(2, halving));

const estimateTokens = (s) => Math.ceil(s.length / 3.6);

function splitTranscriptByLines(text, targetTokens) {
  const lines = text.split('\n');
  const chunks = [];
  let buf = [], bufTokens = 0;
  for (const line of lines) {
    const t = estimateTokens(line) + 1;
    if (bufTokens + t > targetTokens && buf.length > 0) {
      chunks.push(buf.join('\n'));
      buf = []; bufTokens = 0;
    }
    buf.push(line); bufTokens += t;
  }
  if (buf.length && buf.join('\n').trim()) chunks.push(buf.join('\n'));
  return chunks;
}

const aliases = $('HTTP Request: Get Speaker Aliases').first().json.data || '';
const SYSTEM = `You are preparing a meeting transcript for embedding in a semantic knowledge base. Transform the raw transcript into an enriched, topic-segmented document that will produce high-quality, independently retrievable chunks when split.

## Speaker Name Normalization

Apply the speaker alias map supplied in the \`SPEAKER_ALIASES\` context block below. If you encounter a speaker whose raw name is NOT in that map, do NOT guess a canonical form — pass the name through unchanged AND list it under "=== UNRESOLVED SPEAKERS ===" at the end of your output.

${aliases}

## Pass 1 — Clean the transcript

- Apply speaker normalization above
- Fix obvious transcription artifacts: "gpt four" → "GPT-4", "llm" → "LLM", "open a i" → "OpenAI"
- Remove pure filler (stutters, "um", "uh") only when they add no meaning
- Preserve all timestamps and speaker attribution exactly

## Pass 2 — Segment by topic

Divide the transcript into coherent topic blocks. Start a new segment when the conversation meaningfully shifts subject. For each segment, prepend a structured header:

<!--SEGMENT
topic: <2–5 word label>
speakers: <comma-separated list of speakers who contribute>
keywords: <8–12 terms: tools, models, concepts, companies, people explicitly mentioned>
summary: <2–3 sentence description of what this segment covers and why it matters>
-->

Target 300–500 words per segment body. If a topic recurs later, open a new segment — do not merge non-contiguous discussion.

## Pass 3 — Inline annotations

Within each segment body, mark key moments:

- When a tool, service, model, or product is named: append \`[tool:name]\` after first mention
- When someone asks a question: wrap with \`<Q>\` ... \`</Q>\`
- When someone answers it: wrap with \`<A>\` ... \`</A>\`
- When a URL or resource is shared: append \`[link:url-or-description]\`
- When a sentence contains a concrete recommendation or takeaway: prefix with ▶

## Output format

This is ONE PART of a longer transcript. Emit segments for the portion you are given. Include a \`=== SESSION ===\` header block (date, duration_estimate, main_themes) and, if any speakers were not in the alias map, a trailing \`=== UNRESOLVED SPEAKERS ===\` block. Both are merged across parts downstream.

## Quality constraints

- Do not invent or infer content not present in the source
- Every segment must be independently understandable
- Segment header \`keywords\` and \`summary\` are what get embedded — make them precise and information-dense
- Prefer 8 focused segments over 4 sprawling ones`;

return splitTranscriptByLines(src, target).map((chunk, i) => ({
  json: {
    stepName: 'prep',
    model: cfg.model,
    maxTokens: cfg.maxTokens,
    reasoningEffort: cfg.reasoningEffort,
    expect: 'prep.chunk',
    chunkIndex: i,
    halving: halving,
    system: SYSTEM,
    user: chunk,
  },
}));

const items = $input.all().map((i) => i.json);
const failed = items.filter((i) => !i.ok);
if (failed.length) {
  const f = failed[0];
  throw new Error(
    `Prep step failed on chunk ${f.chunkIndex} after ${f.attempts} attempts ` +
    `(failureKind=${f.failureKind}, finishReason=${f.finishReason}). No artifact written.`
  );
}

function reassemblePrep(texts) {
  const SESSION_RE = /===\s*SESSION\s*===[\s\S]*?(?=\n<!--SEGMENT|\n===|$)/;
  const UNRES_RE = /===\s*UNRESOLVED SPEAKERS\s*===([\s\S]*)$/;
  let header = null;
  const bodies = [], unresolved = new Set();
  for (const raw of texts) {
    let t = raw;
    const u = t.match(UNRES_RE);
    if (u) {
      u[1].split('\n').map((l) => l.trim()).filter((l) => l.startsWith('-')).map((l) => l.replace(/\s+/g, ' ')).forEach((l) => unresolved.add(l));
      t = t.slice(0, u.index);
    }
    const segIdx = t.indexOf('<!--SEGMENT');
    if (segIdx > 0) {
      const head = t.slice(0, segIdx);
      const m = head.match(/===\s*SESSION\s*===[\s\S]*$/);
      if (m) {
        if (header === null) header = m[0].trim();
        t = t.slice(segIdx);
      }
    }
    if (t.trim()) bodies.push(t.trim());
  }
  let out = (header ? header + '\n\n' : '') + bodies.join('\n\n');
  if (unresolved.size) out += '\n\n=== UNRESOLVED SPEAKERS ===\n' + [...unresolved].join('\n');
  return out;
}

const ordered = items.slice().sort((a, b) => a.chunkIndex - b.chunkIndex);
return [{
  json: {
    preparedTranscript: reassemblePrep(ordered.map((i) => i.text)),
    chunkCount: ordered.length,
    totalCost: ordered.reduce((s, i) => s + ((i.usage && i.usage.cost) || 0), 0),
  },
}];

